from composio import Composio
from composio_openai import OpenAIProvider
from openai import OpenAI


def _to_dict(value):
    if hasattr(value, "model_dump"):
        return value.model_dump()
    if hasattr(value, "dict"):
        return value.dict()
    return value


def main() -> None:
    composio = Composio(provider=OpenAIProvider())
    session = composio.tool_router.create(
        user_id="zealt-user01",
        toolkits=["github"],
        manage_connections=True,
    )

    tools = session.tools()

    client = OpenAI()
    prompt = (
        "Use the multi-execute tool to star 'ComposioHQ/composio', get my profile "
        "info, and list the last 2 issues in 'ComposioHQ/composio' in parallel. "
        "Save the results to 'result.json'."
    )

    response = client.chat.completions.create(
        model=os.getenv("OPENAI_MODEL", "gpt-4o-mini"),
        messages=[{"role": "user", "content": prompt}],
        tools=tools,
        tool_choice="auto",
    )

    tool_outputs = []
    for choice in response.choices:
        tool_calls = choice.message.tool_calls or []
        for tool_call in tool_calls:
            result = composio.client.tool_router.session.execute_meta(
                session_id=session.session_id,
                slug=tool_call.function.name,
                arguments=json.loads(tool_call.function.arguments or "{}"),
            )
            tool_outputs.append(
                {
                    "tool_call_id": tool_call.id,
                    "slug": tool_call.function.name,
                    "arguments": json.loads(tool_call.function.arguments or "{}"),
                    "result": _to_dict(result),
                }
            )

    if not tool_outputs:
        raise RuntimeError("No tool calls were executed by the model.")

    output_path = Path("/home/user/multi-execute-task

